S.DIRS = { "export", "import" }
S.GREY = "ui_font_inactive_grey"       -- CA's own, out of db/ui_colours_tables (102,102,102)
S.BEIGE = "ui_font_faded_grey_beige"   -- likewise (169,159,137): the section row's label
